sources.src/consumer-policy.ts:
export function consumerRefund(
  price: number, daysSincePurchase: number, isFinalSale: boolean,
  hasReceipt: boolean, customerName: string,
) {
  return daysSincePurchase <= 30 && !isFinalSale;
}

sources.src/enterprise-policy.ts:
export function enterpriseRefund(
  price: number, daysSincePurchase: number, isFinalSale: boolean,
  hasReceipt: boolean, customerName: string,
) {
  const contractedWindow = 90;
  return daysSincePurchase <= contractedWindow && hasReceipt;
}

sources.src/refund-amount.ts:
export function calculateRefund(
  price: number, daysSincePurchase: number, isFinalSale: boolean,
  hasReceipt: boolean, customerName: string,
) {
  return Math.max(0, price - Math.round(price * 0.05));
}

sources.src/notification.ts:
export function buildNotification(
  price: number, daysSincePurchase: number, isFinalSale: boolean,
  hasReceipt: boolean, customerName: string,
) {
  return `${customerName}: ${price} yen refunded`;
}

